Agent 检查完系统后会返回这种数据。我想在这条回答里看到检查结果：通过的项目简单列出来，失败的项目突出显示，点击失败项能展开原因，还能复制错误详情。

{
  "type": "CUSTOM",
  "name": "app.inspection.result",
  "value": {
    "target": "订单服务",
    "checks": [
      {
        "name": "数据库连接",
        "status": "passed"
      },
      {
        "name": "支付接口",
        "status": "failed",
        "detail": {
          "code": "UPSTREAM_TIMEOUT",
          "message": "支付接口响应超时",
          "duration_ms": 5000
        }
      }
    ]
  }
}

